#!/bin/sh
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/youtube-id.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'youtube-id.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s %s\n' "${0##*/}" '<youtube-channel-url-or-handle>'
	printf '%s\n' 'Print the channel id (UC...) found at the given channel URL or @handle.'
	exit 0;; esac; done
# shellcheck source=util/lib/build-id.sh
. "$(dirname "$(realpath "$0")")/lib/build-id.sh"; build_flags "$0" "$@"
set -eu
set -o pipefail

url="${1:-}"

if [ -z "$url" ]; then
  echo "usage: youtube-id <youtube-channel-url-or-handle>" >&2
  exit 2
fi

case $url in
  @*) url="https://www.youtube.com/$url" ;;
esac

id="$(
  curl -fsSL "$url" |
    grep -oE '"(channelId|externalId)":"UC[^"]+' |
    head -1 |
    cut -d'"' -f4
)"

if [ -z "$id" ]; then
  echo "No YouTube channel ID found for: $url" >&2
  exit 1
fi

printf '%s\n' "$id"
